#!/usr/bin/env bash
# Read-only: Pricing Term Count vs quote term and line term/dates on recent QA plan lines
sf data query --query "SELECT Quote.QuoteNumber, Quote.RLM_TermMonths__c, Product2.ProductCode, PricebookEntry.ProductSellingModel.Name, BillingFrequency, StartDate, EndDate, SubscriptionTerm, PricingTermCount, NetUnitPrice, TotalPrice, CreatedDate FROM QuoteLineItem WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT','MB-TAM','MB-PAY') ORDER BY CreatedDate DESC LIMIT 25" --target-org target --json 2>&1 | jq -r '.result.records[]? | [.Quote.QuoteNumber, "qTerm", .Quote.RLM_TermMonths__c, .Product2.ProductCode, .PricebookEntry.ProductSellingModel.Name, .BillingFrequency, .StartDate, .EndDate, "subTerm", .SubscriptionTerm, "PTC", .PricingTermCount, "net", .NetUnitPrice, "total", .TotalPrice, .CreatedDate[0:10]] | map(tostring) | join(" ")'
